<!--
 * @Description: 百度地图手动选点获取路段点位（一个一个点，最后一个是终点） 页面
 * @Author: mhf
 * @Date: 2024/2/21 11:55
-->
<template>
  <el-dialog
    width="1300px"
    v-dialog-out
    destroy-on-close
    append-to-body
    v-if="dialogVisible"
    :title="title"
    :visible.sync="dialogVisible"
    :before-close="hideDialog"
    :close-on-click-modal="false"
  >
    <div class="dialog-body">
      <div id="map-container"></div>

      <div class="dialog-body-search">
        <el-input
          @input="searchPlace"
          @clear="searchPlace"
          clearable
          v-model="searchText"
          size="small"
          placeholder="输入关键字查询"
        ></el-input>
      </div>

      <div>
        <div class="dialog-body-res" v-if="searchRes.length > 0">
          <div
            v-for="(item, index) in searchRes"
            :key="index"
            @click="chooseIt(item)"
          >
            <el-tooltip
              effect="light"
              :content="item.address + item.title"
              placement="right-end"
              overflow
            >
              <span> {{ item.address + item.title }} </span>
            </el-tooltip>
          </div>
        </div>
        <div
          class="dialog-body-none"
          v-else-if="searchRes.length === 0 && searchText"
        >
          <em> 没有搜索结果... </em>
        </div>
      </div>
    </div>

    <div class="dialog-footer">
      <el-button @click="hideDialog">取 消</el-button>
      <el-button type="primary" @click="submitPoints">确 定</el-button>
    </div>
  </el-dialog>
</template>

<script>
import { deepClone } from "@/utils/deepClone";

export default {
  name: "handleGetPOld",
  components: {},
  props: {},
  dicts: [],
  data() {
    return {
      dialogVisible: false,
      title: "",
      bdMap: null,
      mapCenter: {
        lng: 120.73957130336815, // 经度
        lat: 30.748406263284365,
      }, // 地图中心点
      mapZoom: 14, // 地图缩放级别
      startPoint: {
        lng: 120.73248921943994,
        lat: 30.757405565825934,
      },
      endPoint: {
        lng: 120.72616347287348,
        lat: 30.75704244981831,
      },
      drivingTime: 0, // 驾驶时间 分钟
      drivingDistance: 0, // 行驶距离 公里
      pointsArr: [
        // {
        //   lat: 30.748406263284365,
        //   lng: 120.73957130336815
        // },
        // {
        //   lat: 30.748406263284365,
        //   lng: 120.73957130336815
        // },
        // {
        //   lat: 30.748406263284365,
        //   lng: 120.73957130336815
        // }
      ], // 最终保存的点位信息 （路段中的所有点位[包含：起点，终点]）
      mapClickListener: null, // 地图点击事件监听器
      drawIndex: 0, // 点击的次数
      transit: null, // 规划的路径
      searchText: undefined, // 查询的关键字
      searchPoint: {}, // 查找到的点位
      searchRes: [], // 查到结果
    };
  },
  methods: {
    showDialog(data) {
      this.dialogVisible = true;
      this.title = data.title;
      if (data.data) {
        // 回显线段和起点终点
        let pointsArr = JSON.parse(data.data);
        this.pointsArr = pointsArr;
        this.startPoint = pointsArr[0];
        this.endPoint = pointsArr[pointsArr.length - 1];
      } else {
      }
      this.initBdMap(data.data);
    },

    hideDialog() {
      this.bdMap.removeEventListener("click", this.mapClickListener);
      this.mapClickListener = null;
      this.bdMap.destroy();
      this.bdMap = null;
      this.dialogVisible = false;
      this.removeSearch();
    },

    removeSearch() {
      // if (this.searchPoint) {
      //   this.removeMarker("searchPoint")
      // }
      this.searchPoint = {};
      this.searchText = undefined;
      this.searchRes = [];
    },

    submitPoints() {
      if (this.pointsArr.length < 2) {
        this.$message.warning("请先绘制线路");
        return;
      }
      this.$emit("on-response", {
        pointsArr: this.pointsArr,
        km: this.drivingDistance,
      });
      this.hideDialog();
    },

    initBdMap(flag) {
      this.$nextTick(() => {
        this.bdMap = new BMapGL.Map("map-container");
        this.bdMap.centerAndZoom(
          new BMapGL.Point(this.mapCenter.lng, this.mapCenter.lat),
          this.mapZoom
        );
        this.bdMap.enableScrollWheelZoom(true);
        if (!flag) {
          // 新增则绘制起点和终点
          this.handleDraw();
        } else {
          // 编辑或者详情则回显绘制的路线
          if (this.pointsArr.length > 0) {
            this.echoLine(); // 回显对应的路线
          } else {
            console.log("没有点位数据");
          }
        }
        setTimeout(() => {
          this.mapResetView([this.startPoint, this.endPoint]);
        }, 500);
      });
    },

    /**
     * @Event 调整地图到最佳视野
     * @param: portArr 点位数组 [pot1, pot2, pot3]
     * @description:
     * @author: mhf
     * @time: 2024-02-01 10:12:24
     **/
    mapResetView(portArr) {
      this.bdMap.setViewport(portArr);
    },

    /**
     * @Event 将路径单位统一成千米
     * @description: 15.9公里 -> 15.9; 500米 -> 0.5
     * @author: mhf
     * @time: 2024-02-01 10:43:07
     **/
    convertDistance(distance) {
      let resKm = 0;
      if (distance.indexOf("公里") > -1) {
        resKm = distance.substring(0, distance.indexOf("公里"));
      } else if (distance.indexOf("米") > -1) {
        resKm = distance.substring(0, distance.indexOf("米")) / 1000;
      } else {
        resKm = distance;
      }
      return resKm;
    },

    /**
     * @Event 绘制点位
     * @param: obj 点位对象,
     * @param: myIcon 自定义图标,
     * @param: customObj 自定义参数,
     * @description: this.makePoint({lng: 116.404, lat: 39.119})
     * @author: mhf
     * @time: 2024-02-01 13:43:13
     **/
    makePoint(obj, myIcon, customObj, isDrag = false) {
      let point = new BMapGL.Point(obj.lng, obj.lat); // 创建点
      let marker = new BMapGL.Marker(point, {
        icon: myIcon ? myIcon : null,
        // enableDragging: isDrag // 实现可拖拽
      }); // 创建标注
      marker.customObj = customObj;
      this.bdMap.addOverlay(marker);

      // 实现点位可以拖拽
      // if (isDrag) {
      //   marker.addEventListener("dragend", (e) => {
      //     const newPosition = e.point; // 获取拖拽后的坐标
      //     console.log("新的位置：", newPosition);
      //   });
      // }

      marker.addEventListener("click", (e) => {
        console.log("点击了标注", e);
      });
    },

    /**
     * @Event 回显路线
     * @description:
     * @author: mhf
     * @time: 2024-02-21 11:25:52
     **/
    echoLine() {
      let pointsGlArr = []; // new BMapGL.Point
      let oldLen = this.pointsArr.length; // 旧的点位数组长度
      const getPointGlArr = () => {
        return this.pointsArr.map(
          (item) => new BMapGL.Point(item.lng, item.lat)
        );
      };
      pointsGlArr = getPointGlArr();
      var polyline = new BMapGL.Polyline(pointsGlArr, {
        strokeStyle: "dashed",
        strokeColor: "blue",
        strokeTexture: {
          url: "/mapopen/svgmodel/Icon_road_blue_arrow.png",
          width: 16,
          height: 64,
        },
        strokeWeight: 8,
        strokeOpacity: 0.8,
      });
      this.bdMap.addOverlay(polyline); // 绘制折线
      let allPoints = polyline.getPoints();
      let startPoint = allPoints[0];
      let endPoint = allPoints[allPoints.length - 1];
      this.makePoint(
        { lng: startPoint.latLng.lng, lat: startPoint.latLng.lat },
        new BMapGL.Icon(
          "/img/baiDuGlMap/startPoint.png",
          new BMapGL.Size(25, 40)
        ),
        { name: "handlePoint" + 0 },
        false
      );
      this.makePoint(
        { lng: endPoint.latLng.lng, lat: endPoint.latLng.lat },
        new BMapGL.Icon(
          "/img/baiDuGlMap/endPoint.png",
          new BMapGL.Size(25, 40)
        ),
        { name: "handlePoint" + allPoints.length - 1 },
        false
      );
      for (let i = 1; i < allPoints.length - 1; i++) {
        this.makePoint(
          { lng: allPoints[i].latLng.lng, lat: allPoints[i].latLng.lat },
          new BMapGL.Icon(
            "/img/baiDuGlMap/handlePoint.png",
            new BMapGL.Size(12, 12)
          ),
          { name: "handlePoint" + i },
          false
        );
      }

      // 设置回显后点击继续绘制路段
      let index = 0;
      this.bdMap.addEventListener("click", (e) => {
        this.pointsArr.push({ lat: e.latlng.lat, lng: e.latlng.lng });
        pointsGlArr = getPointGlArr();
        polyline = new BMapGL.Polyline(pointsGlArr, {
          strokeStyle: "dashed",
          strokeColor: "blue",
          strokeTexture: {
            url: "/mapopen/svgmodel/Icon_road_blue_arrow.png",
            width: 16,
            height: 64,
          },
          strokeWeight: 8,
          strokeOpacity: 0.8,
        });
        this.bdMap.addOverlay(polyline);

        // 将终点的图标换成handlePoint最新点击的点位图标则为endPoint
        index++;
        let allPoints = polyline.getPoints();
        let whichPoint = allPoints[allPoints.length - 1]; // 获取最后一个点位
        this.makePoint(
          { lng: whichPoint.latLng.lng, lat: whichPoint.latLng.lat },
          new BMapGL.Icon(
            "/img/baiDuGlMap/endPoint.png",
            new BMapGL.Size(25, 40)
          ),
          { name: "handlePointNewEdit" + index },
          false
        );
        allPoints = polyline.getPoints();
        let markerArr = this.bdMap.getOverlays(); // 获取所有的点位
        for (let i = 1; i < allPoints.length - 1; i++) {
          this.bdMap.removeOverlay(markerArr[i + 1]); // 移除所有点位
          this.makePoint(
            { lng: allPoints[i].latLng.lng, lat: allPoints[i].latLng.lat },
            new BMapGL.Icon(
              "/img/baiDuGlMap/handlePoint.png",
              new BMapGL.Size(12, 12)
            ),
            { name: "handlePointNewEdit" + i },
            false
          );
        }
      });
    },

    /**
     * @Event 手动绘制折现（自己选择点位绘制）
     * @description:
     * @author: mhf
     * @time: 2024-02-20 17:20:10
     **/
    handleDraw() {
      this.drawIndex = 0;
      this.pointsArr = [];
      let pointsGlArr = []; // new BMapGL.Point
      var node = new BMapGL.Icon(
        "//mapopen-pub-jsapigl.bj.bcebos.com/demoimg/zhongheyiyuan.png",
        new BMapGL.Size(11, 11),
        {
          offset: new BMapGL.Size(5, 5),
        }
      );

      this.mapClickListener = this.bdMap.addEventListener("click", (e) => {
        this.pointsArr.push({ lat: e.latlng.lat, lng: e.latlng.lng });
        pointsGlArr = this.pointsArr.map(
          (item) => new BMapGL.Point(item.lng, item.lat)
        );
        this.makePoint(
          { lng: e.latlng.lng, lat: e.latlng.lat },
          this.getIcon({
            index: this.drawIndex,
            length: this.pointsArr.length,
          }),
          { name: "handlePoint" + this.drawIndex },
          false
        );
        if (this.drawIndex >= 1) {
          // 绘制线段
          var polyline = new BMapGL.Polyline(pointsGlArr, {
            strokeStyle: "dashed",
            strokeColor: "blue",
            strokeTexture: {
              url: "/mapopen/svgmodel/Icon_road_blue_arrow.png",
              width: 16,
              height: 64,
            },
            strokeWeight: 8,
            strokeOpacity: 0.8,
            node: node,
          });
          this.bdMap.addOverlay(polyline); // 绘制折线
          this.drivingDistance = this.convertDistance(
            polyline.getLength() + "米"
          );
          // let a = this.bdMap.getDistance(
          //   {
          //     lat: 30.757710871468586,
          //     lng: 120.726805695988,
          //   },
          //   {
          //     lat: 30.77072443751006,
          //     lng: 120.77038539084762,
          //   }
          // ) // 获取两点之间的距离
          // polyline.enableEditing(); // 折线可编辑
        }
        this.drawIndex++;

        if (this.drawIndex >= 3) {
          let allPoints = polyline.getPoints();
          let whichPoint = allPoints[this.drawIndex - 2];
          let markerArr = this.bdMap.getOverlays(); // 获取所有的点位
          // for (let i = 0; i < markerArr.length; i++) {
          //   if (markerArr[i].customObj?.name === 'handlePoint' + (this.drawIndex - 2)) {
          //     this.bdMap.removeOverlay(markerArr[i]) // 移除指定的点位
          //   }
          // } // 已简化代码如下
          this.bdMap.removeOverlay(
            markerArr.filter(
              (item) =>
                item.customObj?.name === "handlePoint" + (this.drawIndex - 2)
            )[0]
          );
          this.makePoint(
            { lng: whichPoint.latLng.lng, lat: whichPoint.latLng.lat },
            this.getIcon({ index: -1, length: -1, width: 12, height: 12 }),
            { name: "handlePointNew" + this.drawIndex },
            false
          );
          // this.pointsArr = deepClone(this.pointsArr)
        }
      });
    },

    /**
     * @Event 获取图标 (第一个点是起点图标,最后一个点是终点图标，其他是别的图标)
     * @description:
     * @author: mhf
     * @time: 2024-02-21 14:21:40
     **/
    getIcon(params) {
      let { index, length, width = 25, height = 40 } = params;
      return new BMapGL.Icon(
        `/img/baiDuGlMap/${
          index === 0
            ? "startPoint"
            : index === length - 1
            ? "endPoint"
            : "handlePoint"
        }.png`,
        new BMapGL.Size(width, height)
      );
    },

    /**
     * @Event 移除点位
     * @description:
     * @author: mhf
     * @time: 2024-02-01 19:36:52
     **/
    removeMarker(name = "startPoint") {
      let markerArr = this.bdMap.getOverlays();
      for (let i = 0; i < markerArr.length; i++) {
        if (markerArr[i].customObj?.name === name) {
          this.bdMap.removeOverlay(markerArr[i]); // 移除所有点位
        }
      }
      // this.bdMap.clearOverlays() // 移除图层
    },

    /**
     * @Event 清除覆盖物
     * @description:
     * @author: mhf
     * @time: 2024-02-19 18:09:56
     **/
    resetLine() {
      this.bdMap.clearOverlays(); // 移除图层
      this.transit?.clearResults(); // 移除绘制的路径（自动绘制路段）
      this.pointsArr = [];
      this.drivingDistance = 0;
      this.drawIndex = 0;
      this.bdMap.removeEventListener("click", this.mapClickListener);
      this.mapClickListener = null;
      this.handleDraw();
    },

    /**
     * @Event 输入关键字查询地点
     * @description:
     * @author: mhf
     * @time: 2024-02-21 15:56:42
     **/
    searchPlace(e) {
      this.searchRes = [];
      if (e) {
        const myFun = () => {
          this.searchRes = local.getResults()._pois;
        };
        var local = new BMapGL.LocalSearch(this.bdMap, {
          onSearchComplete: myFun,
        });
        local.search(e);
      } else {
        this.removeMarker("searchPoint");
      }
    },

    chooseIt(item) {
      this.searchPoint = item.point;
      if (this.searchPoint) {
        this.removeMarker("searchPoint");
      }
      this.makePoint(
        { lng: this.searchPoint.lng, lat: this.searchPoint.lat },
        null,
        { name: "searchPoint" },
        false
      );
      this.bdMap.centerAndZoom(item.point, 18);
    },
  },
  created() {},
  mounted() {},
};
</script>

