<template>
  <back-home-btn>
    <el-form
      ref="form"
      :model="formData"
      :rules="formRules"
      label-width="140px"
    >
      <el-row :gutter="24">
        <el-col :span="24">
          <el-form-item
            label="路段点位(自动) : "
            prop="trafficRoad.roadCoordinate"
          >
            <el-input
              v-model="formData.trafficRoad.roadCoordinate"
              disabled
              placeholder=""
            >
              <template slot="append">
                <div class="choose-class" @click="showLeafletMap('auto')">
                  <i class="iconfont if-ditudingwei" /> <span>选择</span>
                </div>
              </template>
            </el-input>
          </el-form-item>
        </el-col>

        <el-col :span="24">
          <el-form-item
            label="路段点位(手动) : "
            prop="trafficRoad.handCoordinate"
          >
            <el-input
              v-model="formData.trafficRoad.handCoordinate"
              disabled
              placeholder=""
            >
              <template slot="append">
                <div class="choose-class" @click="showLeafletMap('handle')">
                  <i class="iconfont if-ditudingwei" /> <span>选择</span>
                </div>
              </template>
            </el-input>
          </el-form-item>
        </el-col>

        <el-col :span="24">
          <el-form-item
            label="路段点位(选点) : "
            prop="trafficRoad.handPointArr"
          >
            <el-input
              v-model="formData.trafficRoad.handPointArr"
              disabled
              placeholder=""
            >
              <template slot="append">
                <div
                  class="choose-class"
                  @click="showLeafletMap('handlePoint')"
                >
                  <i class="iconfont if-ditudingwei" /> <span>选择</span>
                </div>
              </template>
            </el-input>
          </el-form-item>
        </el-col>

        <el-col :span="24">
          <el-form-item label="路段长度 : " prop="trafficRoad.roadLength">
            <el-input
              v-model="formData.trafficRoad.roadLength"
              placeholder="选择路段点位后自动填充"
              disabled
            >
              <template slot="suffix">
                <span class="slot-class"> km </span>
              </template>
            </el-input>
          </el-form-item>
        </el-col>
      </el-row>
    </el-form>

    <el-button type="primary" @click="validateForm">
      提交点位和路段长度
    </el-button>

    <autoGetP @on-response="getAutoP" ref="autoGetP" />
    <handleGetP @on-response="getHandleP" ref="handleGetP" />
    <handleGetPOld @on-response="getHandlePoint" ref="handleGetPOld" />
  </back-home-btn>
</template>

<script>
import autoGetP from "@/views/bdGlMap/autoGetP.vue";
import handleGetP from "@/views/bdGlMap/handleGetP.vue";
import handleGetPOld from "@/views/bdGlMap/handleGetPOld.vue";
export default {
  name: "bdGlMap",
  components: { autoGetP, handleGetP, handleGetPOld },
  mixins: [],
  props: {},
  computed: {},
  watch: {},
  filters: {},
  data() {
    return {
      formData: {
        trafficRoad: {
          roadProperties: "4",
        },
      },
      formRules: {
        "trafficRoad.roadCoordinate": [
          { required: true, message: "请选择路段点位", trigger: "blur" },
        ],
      },
    };
  },
  methods: {
    validateForm() {
      this.$refs.form.validate((valid) => {
        if (valid) {
          this.submitForm();
        } else {
          return false;
        }
      });
    },

    submitForm() {
      console.log(this.formData);
    },

    showLeafletMap(type) {
      if (type === "handle") {
        let passData = {
          title: "选择线路轨迹",
          data: this.formData.trafficRoad.handCoordinate,
        };
        this.$refs.handleGetP.showDialog(passData);
      } else if (type === "auto") {
        let passData = {
          title: "选择线路轨迹",
          data: this.formData.trafficRoad.roadCoordinate,
        };
        this.$refs.autoGetP.showDialog(passData);
      } else if (type === "handlePoint") {
        let passData = {
          title: "选择线路轨迹",
          data: this.formData.trafficRoad.handPointArr,
        };
        this.$refs.handleGetPOld.showDialog(passData);
      }
    },

    /**
     * @Event 获取组件传递来的数据
     * @description:
     * @author: mhf
     * @time: 2024-02-01 11:23:11
     **/
    getPoints({ km, pointsArr }) {
      console.log(km, pointsArr, "收到的值");
      this.$set(this.formData.trafficRoad, "roadLength", km);
      this.$set(
        this.formData.trafficRoad,
        "roadCoordinate",
        JSON.stringify(pointsArr)
      );
      this.$set(this.formData.trafficRoad, "startLongitude", pointsArr[0].lng);
      this.$set(this.formData.trafficRoad, "startLatitude", pointsArr[0].lat);
      this.$set(
        this.formData.trafficRoad,
        "endLongitude",
        pointsArr[pointsArr.length - 1].lng
      );
      this.$set(
        this.formData.trafficRoad,
        "endLatitude",
        pointsArr[pointsArr.length - 1].lat
      );
    },

    getAutoP({ km, pointsArr }) {
      this.$set(this.formData.trafficRoad, "roadLength", km);
      this.$set(
        this.formData.trafficRoad,
        "roadCoordinate",
        JSON.stringify(pointsArr)
      );
      this.$set(this.formData.trafficRoad, "startLongitude", pointsArr[0].lng);
      this.$set(this.formData.trafficRoad, "startLatitude", pointsArr[0].lat);
      this.$set(
        this.formData.trafficRoad,
        "endLongitude",
        pointsArr[pointsArr.length - 1].lng
      );
      this.$set(
        this.formData.trafficRoad,
        "endLatitude",
        pointsArr[pointsArr.length - 1].lat
      );
    },

    getHandleP({ km, pointsArr }) {
      console.log(km, pointsArr, "收到的值");
      // this.$set(this.formData.trafficRoad, "roadLength", km);
      this.$set(
        this.formData.trafficRoad,
        "handCoordinate",
        JSON.stringify(pointsArr)
      );
      // this.$set(this.formData.trafficRoad, "startLongitude", pointsArr[0].lng);
      // this.$set(this.formData.trafficRoad, "startLatitude", pointsArr[0].lat);
      // this.$set(this.formData.trafficRoad, "endLongitude", pointsArr[pointsArr.length - 1].lng,);
      // this.$set(this.formData.trafficRoad, "endLatitude", pointsArr[pointsArr.length - 1].lat,);
    },

    getHandlePoint({ km, pointsArr }) {
      this.$set(
        this.formData.trafficRoad,
        "handPointArr",
        JSON.stringify(pointsArr)
      );
    },
  },
  created() {},
  mounted() {},
  destroyed() {},
};
</script>

